import React from 'react';
import { C } from '../data';
import FadeIn from './FadeIn';
import SectionHeader from './SectionHeader';

const cards = [
  { icon: '🛡️', title: 'Verified Leads Only', desc: 'Every student request is reviewed before being shared with tutors.' },
  { icon: '⭐', title: 'Quality Focused', desc: 'We prioritise long-term student success over raw numbers.' },
  { icon: '🔗', title: 'Direct Connection', desc: 'We bridge tutors and students — no middleman, full transparency.' },
];

export default function About() {
  return (
    <section id="about" style={{ padding: '96px 24px', background: C.bg }}>
      <div style={{ maxWidth: 1280, margin: '0 auto' }}>
        <SectionHeader tag="About Us" title="Who is TutorBridge?" subtitle="An independent platform dedicated to connecting passionate tutors with students who need them — built on quality, trust, and results." />
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 32 }}>
          {cards.map((c, i) => (
            <FadeIn key={i} delay={i * 0.15}>
              <div
                style={{ padding: 32, borderRadius: 20, border: `1px solid ${C.border}`, background: C.white, textAlign: 'center', boxShadow: '0 4px 20px rgba(26,58,143,0.06)', transition: 'all 0.3s', cursor: 'default' }}
                onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-8px)'; e.currentTarget.style.boxShadow = '0 20px 40px rgba(26,58,143,0.12)'; }}
                onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = '0 4px 20px rgba(26,58,143,0.06)'; }}
              >
                <div style={{ width: 56, height: 56, borderRadius: 16, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 20px', background: C.bluePale, fontSize: 24 }}>
                  {c.icon}
                </div>
                <h3 style={{ fontWeight: 700, fontSize: 17, marginBottom: 10, color: C.text }}>{c.title}</h3>
                <p style={{ fontSize: 14, lineHeight: 1.7, color: C.muted }}>{c.desc}</p>
              </div>
            </FadeIn>
          ))}
        </div>
      </div>
    </section>
  );
}
